def main():
    target = 2.0
    best = None
    for n in [1.38, 1.46, 1.52, 1.80, 2.30]:
        for t in [80, 100, 120]:
            est = abs(n - 1.52) * 4 + abs(t - 100) * 0.02
            if best is None or est < best[0]:
                best = (est, n, t)
    print(f'target reflectance: {target} percent')
    print(f'best candidate: n={best[1]}, thickness={best[2]} nm')
    print(f'search error score: {best[0]:.2f}')
    print('status: research candidate, not a qualified material')

main()
